const crypto = require('crypto');

class ConsistentHash {
  constructor(replicas = 100) {
    this.replicas = replicas;
    this.ring = new Map();
    this.nodes = new Set();
  }

  // Hash function using MD5
  _hash(key) {
    return crypto.createHash('md5').update(key).digest('hex');
  }

  addNode(node) {
    this.nodes.add(node);
    for (let i = 0; i < this.replicas; i++) {
      const hash = this._hash(`${node}:vnode:${i}`);
      this.ring.set(hash, node);
    }
  }

  getNode(key) {
    if (this.ring.size === 0) return null;
    const hash = this._hash(key);
    // Find the next node on the ring (clockwise)
    for (const [ringHash, node] of this.ring) {
      if (hash <= ringHash) return node;
    }
    // Wrap around to first node
    return this.ring.values().next().value;
  }
}

using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public class ConsistentHashRing
{
    private readonly int _replicas;
    private readonly SortedDictionary<uint, string> _ring = new();
    private readonly List<string> _nodes = new();

    public ConsistentHashRing(int replicas = 100)
    {
        _replicas = replicas;
    }

    private uint ComputeHash(string key)
    {
        var bytes = Encoding.UTF8.GetBytes(key);
        var hash = MD5.HashData(bytes);
        return BitConverter.ToUInt32(hash, 0);
    }

    public void AddNode(string node)
    {
        _nodes.Add(node);
        for (var i = 0; i < _replicas; i++)
        {
            var hash = ComputeHash($"{node}:vnode:{i}");
            _ring[hash] = node;
        }
    }

    public string? GetNode(string key)
    {
        if (_ring.Count == 0) return null;
        var hash = ComputeHash(key);
        foreach (var kvp in _ring)
        {
            if (hash <= kvp.Key) return kvp.Value;
        }
        return _ring.Values.First();
    }
}
